import { createServer, type Server } from "node:http";

type OwnedRuntime =
  | "metadata"
  | "litellm"
  | "ollama"
  | "lm-studio"
  | "llamacpp";

export type DescriptorRuntimeFixtures = {
  env: Readonly<Record<string, string>>;
  requests: Array<{
    runtime: OwnedRuntime;
    method: string;
    path: string;
    caseName: string;
  }>;
  setCaseLabel: (name: string) => void;
  pinRuntimeEndpoints: () => void;
  close: () => Promise<void>;
};

/**
 * Descriptor/status tests exercise real built HTTP paths. Their baseline local
 * runtimes are unavailable, while dynamic metadata loads successfully from an
 * owned first source. No real daemon, external registry or credential is used.
 */
export async function startDescriptorRuntimeFixtures(): Promise<DescriptorRuntimeFixtures> {
  const servers: Server[] = [];
  const requests: DescriptorRuntimeFixtures["requests"] = [];
  const previous = new Map<string, string | undefined>();
  let caseName = "suite bootstrap";

  /** Close only these ready listeners and wait for their active requests to settle. */
  async function closeServers(): Promise<void> {
    await Promise.all(
      servers.map(
        (server) =>
          new Promise<void>((resolve, reject) => {
            server.close((error) => (error ? reject(error) : resolve()));
            server.closeIdleConnections();
          }),
      ),
    );
  }

  /** Bind a real ephemeral listener and journal requests received by that runtime. */
  async function start(runtime: OwnedRuntime): Promise<string> {
    const server = createServer((req, res) => {
      const path = new URL(req.url ?? "/", "http://owned.invalid").pathname;
      requests.push({ runtime, method: req.method ?? "", path, caseName });
      if (runtime === "metadata") {
        if (req.method === "HEAD" && path === "/health") {
          res.writeHead(200);
          res.end();
          return;
        }
        if (req.method === "GET" && path === "/api/v1/models") {
          res.writeHead(200, { "Content-Type": "application/json" });
          res.end(
            JSON.stringify({
              version: "descriptor-owned-v1",
              lastUpdated: "2026-10-14T00:00:00.000Z",
              models: {},
              aliases: {},
              defaults: {},
            }),
          );
          return;
        }
        res.writeHead(404);
        res.end();
        return;
      }
      // A real, deterministic failure preserves "unavailable local runtime"
      // controls without relying on an unowned dead port or host daemon.
      res.writeHead(503, { "Content-Type": "application/json" });
      res.end(
        JSON.stringify({ error: "descriptor-suite-runtime-unavailable" }),
      );
    });
    await new Promise<void>((resolve, reject) => {
      const onError = (error: Error) => reject(error);
      server.once("error", onError);
      server.listen(0, "127.0.0.1", () => {
        server.off("error", onError);
        resolve();
      });
    });
    servers.push(server);
    const address = server.address();
    if (!address || typeof address === "string") {
      throw new Error("descriptor fixture did not report its owned port");
    }
    return `http://127.0.0.1:${address.port}`;
  }

  try {
    const metadata = await start("metadata");
    const litellm = await start("litellm");
    const ollama = await start("ollama");
    const lmStudio = await start("lm-studio");
    const llamaCpp = await start("llamacpp");
    const env: DescriptorRuntimeFixtures["env"] = {
      MODEL_CONFIG_URL: `${metadata}/api/v1/models`,
      LITELLM_BASE_URL: litellm,
      OLLAMA_BASE_URL: ollama,
      OLLAMA_API_BASE: ollama,
      LM_STUDIO_BASE_URL: `${lmStudio}/v1`,
      LLAMACPP_BASE_URL: `${llamaCpp}/v1`,
    };
    for (const key of Object.keys(env)) {
      previous.set(key, process.env[key]);
    }
    /** Restore owned routes after a case deliberately clears its environment. */
    const pinRuntimeEndpoints = () => {
      for (const [key, value] of Object.entries(env)) {
        process.env[key] = value;
      }
    };
    pinRuntimeEndpoints();
    return {
      env,
      requests,
      setCaseLabel: (name) => {
        caseName = name;
      },
      pinRuntimeEndpoints,
      /** Release owned listeners and restore every pinned environment entry. */
      close: async () => {
        try {
          await closeServers();
        } finally {
          for (const [key, value] of previous) {
            if (value === undefined) {
              delete process.env[key];
            } else {
              process.env[key] = value;
            }
          }
          console.log("DESCRIPTOR_OWNED_REQUESTS", JSON.stringify(requests));
        }
      },
    };
  } catch (error) {
    await closeServers();
    throw error;
  }
}

/**
 * Synthesised audio/video fixtures for the multimodal suites.
 *
 * The fixtures are generated with ffmpeg at test time rather than committed.
 * Real media is the only thing that exercises these processors — `music-metadata`
 * and `ffprobe` both read container headers, so a hand-rolled byte string proves
 * nothing — but committing binaries to grow the repo for every codec and edge
 * case is a poor trade when ffmpeg can mint them deterministically.
 *
 * CI already installs ffmpeg (`AnimMouse/setup-ffmpeg` in ci.yml). Where it is
 * absent, callers should skip rather than fail: a missing local tool is not a
 * product defect.
 */

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import * as fs from "node:fs";
import * as path from "node:path";

const execFileAsync = promisify(execFile);

/**
 * Resolve an ffmpeg binary.
 *
 * Absolute candidates are checked BEFORE the bare name. Returning "ffmpeg"
 * first would end the search there, so a machine whose PATH lacks ffmpeg but
 * which has it at /usr/bin/ffmpeg would report "not available" and silently
 * skip every media suite.
 */
export function findFfmpeg(): string | null {
  const explicit = process.env.FFMPEG_PATH;
  if (explicit && fs.existsSync(explicit)) {
    return explicit;
  }

  for (const absolute of [
    "/opt/homebrew/bin/ffmpeg",
    "/usr/local/bin/ffmpeg",
    "/usr/bin/ffmpeg",
  ]) {
    if (fs.existsSync(absolute)) {
      return absolute;
    }
  }

  // Last resort: let execFile resolve it through PATH. hasFfmpeg() proves it
  // actually runs, so a bare name that does not resolve fails there, not here.
  return "ffmpeg";
}

/** True when ffmpeg can actually be invoked, not merely located. */
export async function hasFfmpeg(): Promise<boolean> {
  const bin = findFfmpeg();
  if (!bin) {
    return false;
  }
  try {
    await execFileAsync(bin, ["-version"]);
    return true;
  } catch {
    return false;
  }
}

/**
 * Generate a tone as a real audio file.
 *
 * A sine source rather than silence: some encoders emit a degenerate stream for
 * pure silence, and the point is to exercise a normal decode path.
 */
export async function makeAudioFile(
  dir: string,
  name: string,
  seconds = 2,
  extraArgs: string[] = [],
): Promise<string> {
  const bin = findFfmpeg();
  if (!bin) {
    throw new Error("ffmpeg unavailable");
  }
  const out = path.join(dir, name);
  await execFileAsync(bin, [
    "-y",
    "-f",
    "lavfi",
    "-i",
    `sine=frequency=440:duration=${seconds}`,
    ...extraArgs,
    out,
  ]);
  return out;
}

/** Generate a short colour-bar video with an audio track. */
export async function makeVideoFile(
  dir: string,
  name: string,
  seconds = 2,
  extraArgs: string[] = [],
): Promise<string> {
  const bin = findFfmpeg();
  if (!bin) {
    throw new Error("ffmpeg unavailable");
  }
  const out = path.join(dir, name);
  // The audio encoder is pinned rather than left to the muxer default: ffmpeg
  // does not guarantee a particular default encoder for MP4, so a test that
  // asserts on the resulting audio codec would be asserting on the local build
  // configuration. `extraArgs` still wins, since it is appended after.
  await execFileAsync(bin, [
    "-y",
    "-f",
    "lavfi",
    "-i",
    `testsrc=size=320x240:rate=10:duration=${seconds}`,
    "-f",
    "lavfi",
    "-i",
    `sine=frequency=440:duration=${seconds}`,
    "-shortest",
    "-pix_fmt",
    "yuv420p",
    "-c:a",
    "aac",
    ...extraArgs,
    out,
  ]);
  return out;
}

/**
 * A file with a valid extension whose bytes are not that format.
 *
 * The interesting failure is not "no file" but "file that lies about itself" —
 * a truncated upload or a mislabelled download, which is what reaches these
 * processors in practice.
 */
export function makeCorruptFile(dir: string, name: string): string {
  const out = path.join(dir, name);
  fs.writeFileSync(out, Buffer.from("not really media, just ascii", "utf8"));
  return out;
}

/**
 * Render a number into an image of a chosen byte size.
 *
 * Two properties matter and neither is incidental.
 *
 * The *content* is a number the model cannot guess. Asking "describe this
 * image" is worthless — a model that received nothing still produces plausible
 * prose — and asking about a property with a strong prior (dimensions, a
 * common colour) is answerable without looking. A four-digit token has no
 * prior, so a correct answer can only have come from the pixels.
 *
 * The *size* is chosen relative to `SIZE_TIER_THRESHOLDS.TINY_MAX` (10 KB).
 * Files under it are processed eagerly; files over it take the lazy
 * reference path. An image on the wrong side of that line silently became a
 * ~98-character text preview and never reached the model at all — and the
 * reason that shipped is that every image fixture in the suites happened to be
 * a few kilobytes. `bigPixels` pushes the encode over the threshold so the
 * lazy path is actually exercised.
 *
 * @param label - Digits rendered into the image; keep it un-guessable.
 * @param bigPixels - When true, render large enough to exceed TINY_MAX.
 */
export async function makeNumberImage(
  dir: string,
  name: string,
  label: string,
  bigPixels = false,
): Promise<string> {
  const magick = findImageMagick();
  if (!magick) {
    throw new Error("ImageMagick unavailable");
  }
  const out = path.join(dir, name);
  const size = bigPixels ? "1600x900" : "200x100";
  const pointsize = bigPixels ? "220" : "48";
  await execFileAsync(magick, [
    "-size",
    size,
    "xc:white",
    "-fill",
    "black",
    "-pointsize",
    pointsize,
    "-gravity",
    "center",
    "-annotate",
    "0",
    label,
    out,
  ]);
  return out;
}

/**
 * Locate ImageMagick: `IMAGEMAGICK_PATH` first, then the usual install roots.
 *
 * Mirrors `findFfmpeg`'s env-override-then-fixed-paths order, so an unusual
 * install can be pointed at rather than making the caller skip. It stops short
 * of `findFfmpeg`'s bare-name PATH fallback on purpose: that one is safe
 * because `hasFfmpeg()` proves the binary runs before anything relies on it,
 * and there is no equivalent probe here — returning "magick" on a machine
 * without it would turn a clean skip into a spawn failure mid-fixture.
 */
export function findImageMagick(): string | null {
  const explicit = process.env.IMAGEMAGICK_PATH;
  if (explicit && fs.existsSync(explicit)) {
    return explicit;
  }

  for (const candidate of [
    "/opt/homebrew/bin/magick",
    "/usr/local/bin/magick",
    "/usr/bin/magick",
    "/opt/homebrew/bin/convert",
    "/usr/bin/convert",
  ]) {
    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }
  return null;
}

/**
 * Write a real PCM WAV file without shelling out to anything.
 *
 * The ffmpeg-backed helpers above are the right tool when a suite needs a
 * specific codec or container, but ffmpeg is deliberately not installed in
 * this repo's CI, so any suite that depends on them can only skip there. WAV
 * is simple enough to emit directly — a 44-byte canonical RIFF header plus
 * signed 16-bit little-endian samples — which makes it the one audio fixture
 * a required check can rely on actually existing.
 *
 * The payload is a sine tone rather than silence for the same reason
 * `makeAudioFile` uses one: a decoder handed a run of zeroes can take a
 * degenerate path, and the point is to exercise a normal decode.
 *
 * @param dir - Directory to write into (must exist)
 * @param name - Filename, e.g. "sample.wav"
 * @param seconds - Duration of the tone
 * @param sampleRate - Samples per second
 * @returns Absolute path to the written file
 */
export function makeWavFile(
  dir: string,
  name: string,
  seconds = 1,
  sampleRate = 16000,
): string {
  const channels = 1;
  const bitsPerSample = 16;
  const bytesPerSample = bitsPerSample / 8;
  const frameCount = Math.max(1, Math.round(seconds * sampleRate));
  const dataBytes = frameCount * channels * bytesPerSample;

  const header = Buffer.alloc(44);
  header.write("RIFF", 0, "ascii");
  // RIFF chunk size counts everything after this field, i.e. total - 8.
  header.writeUInt32LE(36 + dataBytes, 4);
  header.write("WAVE", 8, "ascii");
  header.write("fmt ", 12, "ascii");
  header.writeUInt32LE(16, 16); // PCM fmt chunk length
  header.writeUInt16LE(1, 20); // audioFormat = PCM
  header.writeUInt16LE(channels, 22);
  header.writeUInt32LE(sampleRate, 24);
  header.writeUInt32LE(sampleRate * channels * bytesPerSample, 28); // byteRate
  header.writeUInt16LE(channels * bytesPerSample, 32); // blockAlign
  header.writeUInt16LE(bitsPerSample, 34);
  header.write("data", 36, "ascii");
  header.writeUInt32LE(dataBytes, 40);

  const samples = Buffer.alloc(dataBytes);
  const freq = 440;
  for (let i = 0; i < frameCount; i++) {
    const value = Math.round(
      Math.sin((2 * Math.PI * freq * i) / sampleRate) * 0x3fff,
    );
    samples.writeInt16LE(value, i * bytesPerSample);
  }

  const target = path.join(dir, name);
  fs.writeFileSync(target, Buffer.concat([header, samples]));
  return target;
}

import { randomUUID } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { Server } from "node:net";
import { join } from "node:path";

type JournalRow = {
  kind?: string;
  pid?: number;
  port?: number;
  nonce?: string;
  serverId?: string;
};

export type ListenerBoundary = {
  guardJournalPath?: string;
  guardJournalStart: number;
};

export type ServeReadiness = ListenerBoundary & {
  journalPath: string;
  nonce: string;
};

function journalRows(file: string | undefined): JournalRow[] {
  if (!file || !existsSync(file)) {
    return [];
  }
  const rows: JournalRow[] = [];
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line) {
      continue;
    }
    try {
      const row: unknown = JSON.parse(line);
      if (typeof row === "object" && row !== null) {
        rows.push(row as JournalRow);
      }
    } catch {
      // A still-being-appended line cannot establish readiness.
    }
  }
  return rows;
}

/** Snapshot a read-only journal boundary before the actual server starts. */
export function listenerBoundary(): ListenerBoundary {
  const guardJournalPath = process.env.RECOVERY_PROOF_NETWORK_LOG;
  return {
    guardJournalPath,
    guardJournalStart: journalRows(guardJournalPath).length,
  };
}

function hasActualGuardListener(
  boundary: ListenerBoundary,
  pid: number,
  port: number,
): boolean {
  if (!boundary.guardJournalPath) {
    return true;
  }
  return journalRows(boundary.guardJournalPath)
    .slice(boundary.guardJournalStart)
    .some(
      (row) =>
        row.kind === "owned-listener" && row.pid === pid && row.port === port,
    );
}

/** Await the SDK's actual Node listener and return its OS-selected TCP port. */
export async function nativeListenerPort(
  adapter: { getNativeServer(): unknown },
  boundary: ListenerBoundary,
  timeoutMs: number,
): Promise<number> {
  const server = adapter.getNativeServer();
  if (!(server instanceof Server)) {
    throw new Error("SDK fixture did not expose its actual native Node server");
  }
  const readyWithOwnership = () => {
    const address = server.address();
    return Boolean(
      server.listening &&
      address &&
      typeof address !== "string" &&
      Number.isInteger(address.port) &&
      address.port > 0 &&
      hasActualGuardListener(boundary, process.pid, address.port),
    );
  };
  // A socket may already be bound while its asynchronous listening event is
  // still queued. Under the guard, the event's fresh ownership row is required.
  if (!readyWithOwnership()) {
    await new Promise<void>((resolve, reject) => {
      const cleanup = () => {
        clearTimeout(timer);
        server.off("listening", ready);
        server.off("error", failed);
        server.off("close", closed);
      };
      const ready = () => {
        cleanup();
        resolve();
      };
      const failed = (error: Error) => {
        cleanup();
        reject(error);
      };
      const closed = () =>
        failed(new Error("SDK fixture closed before readiness"));
      const timer = setTimeout(
        () => failed(new Error("SDK fixture listener readiness timed out")),
        timeoutMs,
      );
      server.once("listening", ready);
      server.once("error", failed);
      server.once("close", closed);
      if (readyWithOwnership()) {
        ready();
      }
    });
  }
  const address = server.address();
  if (
    !server.listening ||
    !address ||
    typeof address === "string" ||
    !Number.isInteger(address.port) ||
    address.port <= 0 ||
    address.address !== "127.0.0.1"
  ) {
    throw new Error(
      "SDK fixture must have an actual ready loopback TCP listener",
    );
  }
  if (!hasActualGuardListener(boundary, process.pid, address.port)) {
    throw new Error("SDK fixture listener ownership has not been journaled");
  }
  return address.port;
}

/** Unique record-only child readiness channel; never grants network permission. */
export function serveReadiness(directory: string): ServeReadiness {
  const nonce = randomUUID();
  return {
    ...listenerBoundary(),
    journalPath: join(directory, `server-listener-${nonce}.jsonl`),
    nonce,
  };
}

/** Both actual child readiness and any active guard must agree before dialing. */
export function childListenerReady(
  readiness: ServeReadiness,
  pid: number | undefined,
  port: number,
): boolean {
  if (!pid || !Number.isInteger(port) || port <= 0) {
    return false;
  }
  const rows = journalRows(readiness.journalPath).filter(
    (row) =>
      row.pid === pid && row.nonce === readiness.nonce && row.port === port,
  );
  const last = rows.at(-1);
  return Boolean(
    last?.kind === "server-test-listening" &&
    typeof last.serverId === "string" &&
    hasActualGuardListener(readiness, pid, port),
  );
}
